def fills(din, dout, dirs):
    fills=[]
    H,W=len(din),len(din[0])
    bg=max(set(c for r in din for c in r), key=lambda c: sum(r.count(c) for r in din))
    for i in range(H):
        for j in range(W):
            if din[i][j]==bg:
                for (di,dj) in dirs:
                    a,b=i-di,j-dj; c,d=i+di,j+dj
                    if 0<=a<H and 0<=b<W and 0<=c<H and 0<=d<W and din[a][b]==din[c][d]!=bg:
                        fills.append((i,j)); break
    return set(fills)

